import java.util.*;

class Solution {
    static List<List<Object>> topTerms(String text, int k) {
        Map<String, Integer> counts = new HashMap<>();
        for (String raw : text.trim().split("\\s+")) {
            String word = raw.toLowerCase().replaceAll("^[.,!?:;]+|[.,!?:;]+$", "");
            if (!word.isEmpty()) counts.merge(word, 1, Integer::sum);
        }
        List<Map.Entry<String, Integer>> ranked = new ArrayList<>(counts.entrySet());
        ranked.sort(Map.Entry.<String, Integer>comparingByValue().reversed()
                .thenComparing(Map.Entry.comparingByKey()));
        List<List<Object>> result = new ArrayList<>();
        for (Map.Entry<String, Integer> entry : ranked.subList(0, Math.min(k, ranked.size()))) {
            result.add(List.of(entry.getKey(), entry.getValue()));
        }
        return result;
    }
}
